import { defineRouteMiddleware } from '@astrojs/starlight/route-data';
import { getCollection } from 'astro:content';

// Starlight labels an autogenerated folder group with the folder's name
// (`compute-pipes`). This gives the group the title of the folder's index page
// instead, and falls back to the folder name with its first letter capitalised.
// The index page itself stays in the group, under its own sidebar label.

type Entry = { type: 'link'; href: string; label: string } | { type: 'group'; label: string; entries: Entry[] };

let titles: Map<string, string> | undefined;

async function titlesByHref(base: string): Promise<Map<string, string>> {
	if (!titles) {
		const docs = await getCollection('docs');
		titles = new Map(docs.map((d) => [`${base}/${d.id}/`.replace(/\/+/g, '/'), d.data.title]));
	}
	return titles;
}

function relabel(entries: Entry[], byHref: Map<string, string>): void {
	for (const entry of entries) {
		if (entry.type !== 'group') continue;
		const dirName = entry.label;
		const index = entry.entries.find((e) => e.type === 'link' && e.href.endsWith(`/${dirName}/`));
		const title = index && index.type === 'link' ? byHref.get(index.href) : undefined;
		entry.label = title ?? dirName.charAt(0).toUpperCase() + dirName.slice(1).replace(/-/g, ' ');
		relabel(entry.entries, byHref);
	}
}

export const onRequest = defineRouteMiddleware(async (context) => {
	const byHref = await titlesByHref(import.meta.env.BASE_URL.replace(/\/$/, ''));
	for (const guide of context.locals.starlightRoute.sidebar as Entry[]) {
		if (guide.type === 'group') relabel(guide.entries, byHref);
	}
});
